        wf.stage = 'done'
        wf.receipt = {
          url: found.hit.url,
          evidence: `읽기 전용 확인 — ${found.host} 화면에서 이 캡션을 직접 확인했습니다: “${found.hit.snippet}” (${found.hit.url})`,
          at: Date.now(),
