    // 확인 버튼이 비활성인 채로 굳는다(위 interrupted 분기와 같은 모양의 고착).
    // 잠깐 못 찾는 것은 기다리되, 계속 없으면 자리를 놓아준다.
    const since = verifyMissSince.get(wf.id) ?? Date.now()
