function summarizeSightings(list) {
  const arr = Array.isArray(list) ? list : []
  if (arr.length === 0) return '없음'
  return arr.map((s) => `[${s.url ?? ''} · "${String(s.snippet ?? '').slice(0, 90)}"]`).join(' ')
