input.new_string:
/** 런타임이 **직접 관찰해** 작업에 적는 근거 한 건. 모델은 이 값을 만들 수 없다. */
export interface ReadSighting {
  /** 실제로 관찰된 페이지 주소 */
  url: string
  /** 그 주소의 호스트 */
  host: string
  /** 어느 대조 문구가 보였는가(정규화된 형태) */
