export async function probeVerifyNeedles(
  wc: WebContents, needles: string[],
): Promise<{ needle: string; snippet: string } | null> {
  if (wc.isDestroyed() || needles.length === 0) return null
  const want = needles.filter((n) => typeof n === 'string' && n.length > 0)
  if (want.length === 0) return null
  try {
    const res = (await wc.executeJavaScript(`(function(){
      try {
        var SKIP = 'script,style,noscript,template,textarea,input,select,[contenteditable=""],[contenteditable="true"],[contenteditable="plaintext-only"]';
        var parts = [];
        var walker = document.createTreeWalker(document.body || document.documentElement, NodeFilter.SHOW_TEXT, {
          acceptNode: function (node) {
            var el = node.parentElement;
            if (!el) return NodeFilter.FILTER_REJECT;
            // 작성 중인 글·스크립트 본문은 "화면에 올라간 글" 이 아니다.
            if (el.closest(SKIP)) return NodeFilter.FILTER_REJECT;
            return NodeFilter.FILTER_ACCEPT;
          },
        });
        for (var n = walker.nextNode(); n; n = walker.nextNode()) {
          var t = n.nodeValue;
          if (t) parts.push(t);
        }
        var hay = parts.join(' ').replace(/\s+/g, ' ').trim().toLowerCase();
        if (!hay) return null;
        var needles = ${JSON.stringify(want)};
        for (var i = 0; i < needles.length; i++) {
          var at = hay.indexOf(needles[i]);
          if (at < 0) continue;
          var from = Math.max(0, at - 40);
          return { needle: needles[i], snippet: hay.slice(from, at + needles[i].length + 40).trim().slice(0, 200) };
        }
        return null;
      } catch (e) { return null; }
    })()`, true)) as { needle?: unknown; snippet?: unknown } | null
    if (!res || typeof res.needle !== 'string' || !res.needle) return null
    return { needle: res.needle, snippet: typeof res.snippet === 'string' ? res.snippet : '' }
  } catch {
    return null
  }
}

