    for (var a = 0; a < tagged.length; a++) {
      pushAuthor(tagged[a].getAttribute('data-account') || tagged[a].getAttribute('data-author'));
    }
    if (authors.length === 0) {
      var everything = container.querySelectorAll('*');
      for (var b = 0; b < everything.length; b++) {
        var tx = (everything[b].textContent || '').trim();
        if (/^@[A-Za-z0-9._-]{2,30}$/.test(tx)) pushAuthor(tx);
      }
    }
    if (authors.length === 0) {
      var links = container.querySelectorAll('a[href]');
      for (var c = 0; c < links.length; c++) {
        var p = '';
        try { p = new URL(links[c].getAttribute('href'), location.href).pathname; } catch (e) { continue; }
        var m = /^\\/([A-Za-z0-9._-]{2,30})\\/?$/.exec(p);
        if (m) pushAuthor(m[1]);
      }
    }
    if (authors.length > 1) {
      out.ambiguous = '작성자 표기가 여러 개입니다(' + authors.slice(0, 3).join(', ') + ')';
      return out;
    }
    if (authors.length === 1) { out.author = authors[0]; out.authorScope = 'post'; }

