    var now = Date.now();
    var timeEl = container.querySelector('time[datetime]');
    if (timeEl) {
      var parsed = Date.parse(timeEl.getAttribute('datetime'));
      if (!isNaN(parsed)) {
        out.postedAt = parsed;
        out.postedAtText = ((timeEl.textContent || '').trim() || timeEl.getAttribute('datetime') || '').slice(0, 60);
      }
    }
    if (!out.postedAt) {
