        for (var u = 0; u < UNITS.length; u++) {
          var mm = UNITS[u].re.exec(st);
          if (mm) { out.postedAt = now - (parseInt(mm[1], 10) * UNITS[u].ms); out.postedAtText = st; break; }
        }
      }
    }
    return out;
  } catch (e) { return null; }
