  setResumeBlock(pubTaskId, '게시를 시작하지 못해 물러났습니다 — 이 작업은 이어갈 수 없습니다.')
  if (!flushTasks()) {
    console.warn('[ai] 게시 작업 차단을 디스크에 다시 확정하지 못했습니다 — 디스크 판본은 생성 시점의 차단 상태로 남습니다.')
  }
  deleteTask(pubTaskId)

