  return {
    host: hostOf(SNS_OPEN_URL[wf.params.platform]),
    needles: verifyNeedlesFromCaption(wf.caption ?? ''),
    // 이 확인 작업이 만들어진 뒤에 본 것만 센다. 예전 확인이 남긴 기록은 지금의 근거가 아니다.
