// 일회용 점검: 인페이지 대조 스크립트의 문법과 **정규식 백슬래시 생존**을 확인한다.
// (셸 인자로 넘기면 이스케이프가 층층이 접혀 점검 자체가 거짓말을 한다 — 파일로 둔다.)
import fs from 'node:fs'

const src = fs.readFileSync('app/dist/main/features/ai/page-actions.js', 'utf8')
const at = src.indexOf('function VERIFY_PROBE_SCRIPT')
if (at < 0) { console.log('NOT FOUND'); process.exit(1) }
let i = src.indexOf('{', at), d = 0, end = -1
for (; i < src.length; i++) {
  const c = src[i]
  if (c === '{') d++
  else if (c === '}') { d--; if (d === 0) { end = i + 1; break } }
}
const fn = new Function('return ' + src.slice(at, end))()
const code = fn(['테스트 문구'])

try { new Function('return ' + code) } catch (e) { console.log('SYNTAX FAIL:', e.message); process.exit(1) }
console.log('SYNTAX OK · len =', code.length)

