const mustHave = [
  String.raw`/\s+/g`,
  String.raw`(\d{1,4})\s*분\s*전`,
  String.raw`^\/([A-Za-z0-9._-]{2,30})\/?$`,
  'role="banner"',
  'data-post-id',
  'authorScope',
]
let bad = 0
for (const n of mustHave) {
  const ok = code.includes(n)
  if (!ok) bad++
  console.log(`  ${ok ? '✓' : '✗'} ${JSON.stringify(n)}`)
}
// 접힘 사고의 지문: `/s+/g` 는 있는데 `/\s+/g` 가 없으면 접힌 것이다.
if (code.includes('/s+/g')) { console.log('  ✗ 접힘 발견: /s+/g 가 코드에 있다'); bad++ }
console.log(bad === 0 ? 'ALL OK' : `문제 ${bad}건`)
process.exit(bad === 0 ? 0 : 1)

