// 탐색용 일회 스크립트: 컴파일된 task-runtime 을 electron 스텁으로 띄울 수 있는지 본다.
// (되면 "태어날 때 막힌 작업" 을 단위 수준에서 직접 증명하는 검사로 승격한다.)
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import { createRequire } from 'node:module'

const require = createRequire(import.meta.url)
const REPO = process.cwd()
const root = fs.mkdtempSync(path.join(os.tmpdir(), 'bb-blocked-'))

const Module = require('module')
const orig = Module._load
Module._load = function (req, ...rest) {
  if (req === 'electron') {
    return {
      app: { getPath: () => root, on: () => {}, isPackaged: false },
      ipcMain: { handle: () => {}, on: () => {} },
      BrowserWindow: class {},
      WebContentsView: class {},
      session: { fromPartition: () => ({}), defaultSession: {} },
    }
  }
  return orig.call(this, req, ...rest)
}

try {
  const tr = require(path.join(REPO, 'app', 'dist', 'main', 'features', 'ai', 'task-runtime.js'))
  console.log('LOADED. exports:', Object.keys(tr).filter((k) => /Task|flush/.test(k)).join(', '))
  const t = tr.createTask({
    instruction: '게시 작업(시험)', tabId: '', windowId: null,
    blockedReason: '저장이 확정되기 전이라 시작할 수 없습니다 — 게시 준비 중입니다.',
  })
  console.log('created:', t && t.id, 'blocked =', JSON.stringify(t && t.resumeBlockedReason))
  console.log('startTask  →', JSON.stringify(tr.startTask(t.id)))
  console.log('resumeTask →', JSON.stringify(tr.resumeTask(t.id)))
  console.log('flushTasks →', tr.flushTasks())
  const file = path.join(root, 'ai-tasks.json')
  const raw = JSON.parse(fs.readFileSync(file, 'utf8'))
  const disk = (raw.tasks || []).find((x) => x.id === t.id)
  console.log('DISK state =', disk && disk.state, '| DISK block =', JSON.stringify(disk && disk.resumeBlockedReason))
} catch (e) {
  console.log('LOAD FAIL:', e.message.slice(0, 300))
}

