  return /^[A-Za-z0-9._-]{2,30}$/.test(s) ? s.toLowerCase() : '';
}
function posOf(el) {
  // 이 요소의 텍스트가 hay 의 어디쯤에서 시작하는가(대략) — map 을 거꾸로 훑어 찾는다.
  for (var q = 0; q < map.length; q++) {
    if (map[q].el && (map[q].el === el || el.contains(map[q].el))) return map[q].end;
